-- ============================================================================
-- MuseumOS — Timeline data snapshot (timeline_companies + timeline_models)
-- Generated from the local dev DB on 2026-06-26.
-- Content: 19 companies, 614 models (613 epocalc, 1 manual). Public-domain
-- (Wikidata / EPOCALC) data — safe to commit and to ship to a public repo.
--
-- PREREQUISITE: run migrations first so the tables exist:
--   pnpm db:migrate          (or: prisma migrate deploy)
--
-- HOW TO RUN ON THE SERVER (pick one):
--   psql "$DATABASE_URL" -f scripts/timeline-data.sql
--   # or inside the Postgres container:
--   docker exec -i <db-container> psql -U museumos -d museumos < scripts/timeline-data.sql
--
-- Re-runnable: wrapped in a transaction; TRUNCATE clears any prior Timeline
-- rows so the load is idempotent. This REPLACES existing Timeline data —
-- if a curator has edited the Timeline on the server, do NOT run this blindly.
-- ============================================================================

BEGIN;

SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;

-- Clear existing Timeline data (CASCADE: models are removed with companies).
TRUNCATE TABLE public.timeline_models, public.timeline_companies RESTART IDENTITY CASCADE;


COMMIT;
